create or replace function public.notify_admins_new_access_request() returns trigger language plpgsql security definer set search_path='' as $$ begin if new.access_status='pending' then insert into public.notifications(recipient_profile_id,type,title,body,link,metadata) select p.id,'access_request','Nouvelle demande d’accès',trim(coalesce(new.first_name,'')||' '||coalesce(new.last_name,''))||' demande l’accès à l’application.','#settings',jsonb_build_object('profile_id',new.id) from public.profiles p where p.role='admin' and p.active=true and p.access_status='approved' and p.id<>new.id; end if; return new; end; $$;
drop trigger if exists trg_notify_admins_new_access_request on public.profiles; create trigger trg_notify_admins_new_access_request after insert on public.profiles for each row execute function public.notify_admins_new_access_request(); revoke all on function public.notify_admins_new_access_request() from public,anon,authenticated;